CREATE TABLE IF NOT EXISTS user_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS conversations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), session_id UUID REFERENCES user_sessions(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id UUID NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('user','assistant','system')), content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS avatar_designs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), session_id UUID REFERENCES user_sessions(id), title TEXT NOT NULL DEFAULT 'My design', status TEXT NOT NULL DEFAULT 'draft', config JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS design_revisions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), design_id UUID NOT NULL REFERENCES avatar_designs(id) ON DELETE CASCADE, revision INTEGER NOT NULL, config JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(design_id,revision));
CREATE TABLE IF NOT EXISTS catalog_items (asset_id BIGINT PRIMARY KEY, name TEXT NOT NULL, price INTEGER, metadata JSONB NOT NULL DEFAULT '{}', checked_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outfit_items (design_id UUID NOT NULL REFERENCES avatar_designs(id) ON DELETE CASCADE, revision INTEGER NOT NULL, asset_id BIGINT NOT NULL REFERENCES catalog_items(asset_id), slot TEXT NOT NULL, price INTEGER, PRIMARY KEY(design_id,revision,asset_id));
CREATE TABLE IF NOT EXISTS design_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), design_id UUID NOT NULL REFERENCES avatar_designs(id) ON DELETE CASCADE, event TEXT NOT NULL, details JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
